head.script:
// 테스트 설명, 유효성 값 설정
//  mergeByRestricCol(options) = mergeCells("byrestriccol", options) 단축 메소드 (mergeOptionStr 인자 없음).
//  options(선택) 전용 검증 : noDraw / keepMerge / fixedRows / fixedCols + 생략.
scwin.tData = {
    "description" : "[gridView > M > mergeByRestricCol]<br/>Body 영역에서 동일값이 연속되는 Cell 을 세로 방향 제한 방식으로 병합합니다.",
    "validation" : [
        "왼쪽 Column 이 병합된 범위 내에서 'bycol' 방식으로 병합을 수행합니다.",
        "displayFormat 등의 포맷 속성이 적용되지 않은 원본 데이터와 초기 Column 위치를 기준으로 병합됩니다.",
        "mergeCells 속성값을 'byrestriccol' 로 설정합니다.",
        "options(선택) 파라미터를 생략하면 기본값(noDraw/keepMerge/fixedRows/fixedCols 모두 false)으로 병합 처리 제어가 동작합니다.",
        "options.noDraw(선택) true 설정 시 GridView 를 갱신하지 않습니다(다회 병합 성능 개선). false(기본) 설정 시 갱신합니다.",
        "options.keepMerge(선택) true 설정 시 고정영역·수동병합 등 기존 병합을 유지합니다. false(기본) 설정 시 기존 병합을 모두 초기화한 후 새로 병합합니다(mergeCellsFixedCols/Rows 속성값은 불변).",
        "options.fixedRows(선택) true 설정 시 fixedRow 고정 영역도 병합 대상이 됩니다(mergeCellsFixedRows 속성값 불변, Body 병합 유지). false(기본) 설정 시 비고정 영역을 대상으로 합니다.",
        "options.fixedCols(선택) true 설정 시 fixedColumn/fixedRightColumn 고정 영역도 병합 대상이 됩니다(mergeCellsFixedCols 속성값 불변, Body 병합 유지). false(기본) 설정 시 비고정 영역을 대상으로 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — M_mergeCells_3 과 동일한 사업부/팀/평가등급/비고 6행 계층 데이터.
//  byrestriccol = 왼쪽 Column 이 병합된 범위 내에서 'bycol' 병합(왼쪽 Column 의 upperColumn 기준 제약).
//  · col1 사업부  : 영업본부(0~2행) / 관리본부(3~5행)
//  · col2 팀      : 1팀(0~1행) / 2팀(2행) / 3팀(3~5행)
//  · col3 평가등급 : upperColumn="col1"(사업부) → byrestriccol 시 사업부 병합 범위 내에서 우수 세로병합
//        - 영업본부[0~2] 우수 / 관리본부[3~4] 우수 / 관리본부[5] 보통
//  · col4 비고    : upperColumn 미설정 → 단순 연속값 'bycol' 세로병합(우수[0~4] 통째)
//  fixedRows/fixedCols 옵션 시연 : fixedRow=3(행0~2 영업본부 고정 Row), fixedColumn=1(col1 사업부 고정 Column) 추가.
//   → fixedRow=3 이라 고정 Row 영역(행0~2)에서 col2 1팀[0~1]/2팀[2], col3 우수[0~1]/[2] 처럼 byrestriccol 세로병합이 보임(fixedRows=true 시).
scwin.MERGE_DATA = [
    { "col1": "영업본부", "col2": "1팀", "col3": "우수", "col4": "우수" },
    { "col1": "영업본부", "col2": "1팀", "col3": "우수", "col4": "우수" },
    { "col1": "영업본부", "col2": "2팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "우수", "col4": "우수" },
    { "col1": "관리본부", "col2": "3팀", "col3": "보통", "col4": "보통" }
];



// comp 생성 : 계층형 그리드 1개를 동적 생성한다.
//  ★ mergeCells 속성은 생성 attribute 로 주지 않는다. (생성 후 mergeByRestricCol() 메소드로 적용)
//  ★ col3(평가등급) 에 upperColumn="col1"(사업부) 부여 → byrestriccol(왼쪽 Column 병합범위 제약) 검증용.
//  ★ fixedRow=3(행0~2 고정), fixedColumn=1(col1 고정) + mergeCellsFixedRows/Cols=never
//     → options.fixedRows/fixedCols=true 시 고정 영역(상단 3행/col1)도 병합 대상이 되는지(속성 불변) 검증용.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="사업부→팀→평가등급(upper=사업부) 계층. fixedRow=3(행0~2 영업본부 고정), fixedColumn=1(col1 고정), mergeCellsFixedRows/Cols=never. options 선택 후 mergeByRestricCol 버튼으로 적용"', '', 'label1');

    // 계층형 DataList 생성 (col1~col4) 후 병합 비교용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // fixedRow=3, fixedColumn=1 + 고정영역 병합 속성 초기값 never
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id,
        fixedRow: 3,
        fixedColumn: 1,
        mergeCellsFixedRows: "never",
        mergeCellsFixedCols: "never"
    });

    // target 생성 (mergeCells 속성은 부여하지 않음 → 버튼 클릭 시 메소드로 적용)
    //  · col3(평가등급) 의 upperColumn="col1"(사업부) : byrestriccol 일 때 기준 Column 을 사업부(col1) 로 제약
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:560px;height:320px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeByRestricCol sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column1" value="사업부(고정)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="팀"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="column3" value="평가등급(upper=사업부)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="col3" upperColumn="col1" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 수동 병합(mergeCell) : byrestriccol(세로 병합)이 만들지 않는 '가로 병합'을 수동으로 적용한다.
//  · keepMerge 검증용 사전 병합 — 행5(관리본부 3팀 보통 보통)의 col3~col4 를 colSpan=2 로 가로 병합.
//  · 이후 mergeByRestricCol 을 keepMerge=true 로 실행하면 이 수동 가로병합이 유지되고,
//    keepMerge=false(또는 미설정) 로 실행하면 초기화되어 사라진다.
scwin.btn_manualMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    // 행5 col3(colIndex 2) ~ col4 가로 병합(colSpan=2)
    target1.mergeCell({ "rowIndex": 5, "colIndex": 2, "rowSpan": 1, "colSpan": 2 });

    bottom.setReturnValue("[수동 병합] mergeCell 로 행5 [col3~col4] 가로병합(colSpan=2) 적용.");
    bottom.setReturnValue("→ 이제 keepMerge=true 로 mergeByRestricCol 실행 시 이 가로병합 유지 / keepMerge=false(또는 미설정) 시 초기화 확인.");
    scwin.printMergeState(bottom);
}



// mergeByRestricCol 실행 : par_ 값으로 options 를 구성하여 target1.mergeByRestricCol() 호출
//  · 첫 인자가 options(선택) — mergeOptionStr 인자 없음.
//  · options(선택) : noDraw/keepMerge/fixedRows/fixedCols 중 '미설정'이 아닌 키만 담아 구성.
//    4개 모두 미설정이면 options 인자 자체를 생략하여 target1.mergeByRestricCol() 호출(필수여부 N param 생략 로직).
scwin.btn_mergeByRestricCol_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    // options 구성 : '미설정'(빈 라벨)이 아닌 par_ 값만 boolean 으로 담는다.
    //  · gdl_boolean 의 value 는 위치 인덱스('1'/'2'/'3')이고 의미는 label('','true','false')에 있으므로
    //    getValue() 가 아닌 getText() 로 true/false/미설정(빈 라벨)을 판정한다.
    let vNoDraw    = par_noDraw.getText();
    let vKeepMerge = par_keepMerge.getText();
    let vFixedRows = par_fixedRows.getText();
    let vFixedCols = par_fixedCols.getText();

    let options = {};
    let usedKeys = [];
    if (vNoDraw !== '')    { options.noDraw    = (vNoDraw === 'true');    usedKeys.push("noDraw=" + options.noDraw); }
    if (vKeepMerge !== '') { options.keepMerge = (vKeepMerge === 'true'); usedKeys.push("keepMerge=" + options.keepMerge); }
    if (vFixedRows !== '') { options.fixedRows = (vFixedRows === 'true'); usedKeys.push("fixedRows=" + options.fixedRows); }
    if (vFixedCols !== '') { options.fixedCols = (vFixedCols === 'true'); usedKeys.push("fixedCols=" + options.fixedCols); }

    let hasOptions = usedKeys.length > 0;

    // 메소드 호출 직전 mergeCells 속성값 캡처 (before → after 비교용)
    let beforeMerge = target1.options.mergeCells;

    // 필수여부 N 인 options 가 모두 미설정이면 인자 자체를 생략
    if (hasOptions) {
        target1.mergeByRestricCol(options);
    } else {
        target1.mergeByRestricCol();
    }

    if (options.noDraw === true) {
        bottom.setReturnValue("[옵션] noDraw=true → mergeByRestricCol 호출만으로는 화면 미갱신. 화면 갱신은 다음 병합/refresh 시 반영됨.");
    }

    // mergeCells 속성값이 'byrestriccol' 로 변경되는지 before → after 출력
    bottom.setReturnValue("[속성] mergeCells 속성값 : '" + (beforeMerge || '(미설정)') + "' → '" + target1.options.mergeCells + "'" + (beforeMerge !== target1.options.mergeCells ? " (메소드 호출로 변경됨)" : " (이미 동일값)") + " / options={" + (hasOptions ? usedKeys.join(", ") : "(생략)") + "}");
    bottom.setReturnValue("[고정영역속성] mergeCellsFixedRows=" + target1.options.mergeCellsFixedRows + " / mergeCellsFixedCols=" + target1.options.mergeCellsFixedCols + " (fixedRows/fixedCols 옵션 사용해도 불변)");

    scwin.printMergeState(bottom);
}



// 병합 상태 확인 : 각 Body td 의 rowSpan/colSpan 을 읽어 세로(⬇)/가로(➡)/블록(⬛) 병합 그룹을 출력
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 흡수되어 표시되지 않는 td 와 중복 키(고정/스크롤 영역 중복 id)는 제외
//  - 고정 영역(행0/col1) td 도 표시되므로 fixedRows/fixedCols 옵션 시 고정 영역 병합도 함께 출력됨
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let modeName;
    if (rowSpanCnt === 0 && colSpanCnt === 0) modeName = "병합 없음";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) modeName = "세로(rowSpan) 병합";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) modeName = "가로(colSpan) 병합";
    else modeName = "혼합(블록) 병합";

    bottom.setReturnValue("판정 : " + modeName + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
}
